% Units used in createSensors and createDrivingScenario
% Distance/Position - meters
% Speed             - meters/second
% Angles            - degrees
% RCS Pattern       - dBsm

function [sensors, numSensors] = createSensors(scnro)
% createSensors Returns all sensor objects to generate detections

% Assign into each sensor the physical and radar profiles for all actors
profiles = actorProfiles(scnro);
sensors{1} = visionDetectionGenerator(SensorIndex = 1, ...
    SensorLocation = [1.5 0], ...
    DetectorOutput = 'Objects only', ...
    Intrinsics = cameraIntrinsics([800 800],[320 240],[480 640]), ...
    ActorProfiles = profiles);
sensors{2} = drivingRadarDataGenerator(SensorIndex = 2, ...
    MountingLocation = [3.56 -0.9 0.2], ...
    MountingAngles = [-170 0 0], ...
    TargetReportFormat = 'Detections', ...
    Profiles = profiles);
sensors{3} = drivingRadarDataGenerator(SensorIndex = 3, ...
    MountingLocation = [3.51 0.9 0.2], ...
    MountingAngles = [169.159694545669 0 0], ...
    TargetReportFormat = 'Detections', ...
    Profiles = profiles);
sensors{4} = insSensor(TimeInput = true);
numSensors = 4;

function [scnro, egoVehicle] = createDrivingScenario
% createDrivingScenario Returns the drivingScenario defined in the Designer

% Construct a drivingScenario object.
scnro = drivingScenario;

% Add all road segments
roadCenters = [49.3 23.8 0;
    -1.6 9.6 0;
    -1.6 -3.8 0;
    48.5 -20.5 0];
laneSpecification = lanespec(2);
road(scnro, roadCenters, Lanes = laneSpecification, Name = 'Road');

% Add the actors
bicycle = actor(scnro, ...
    ClassID = 3, ...
    Length = 1.7, ...
    Width = 0.45, ...
    Height = 1.7, ...
    Position = [-4.6 2.7 0], ...
    Mesh = driving.scenario.bicycleMesh, ...
    Name = 'Bicycle');
waypoints = [-4.6 2.7 0;
    -3.8 -2.5 0;
    -1.6 -7.6 0;
    1.3 -12.4 0;
    5.6 -16.1 0;
    10.3 -19.6 0;
    16.2 -22.2 0;
    23.2 -23.7 0;
    29.9 -24.1 0;
    36 -24 0;
    39.3 -23.8 0;
    44 -22.9 0;
    47.6 -22 0];
speed = [15;15;15;15;15;15;15;15;15;15;15;15;15];
trajectory(bicycle, waypoints, speed);

% Add the ego vehicle
egoVehicle = vehicle(scnro, ...
    ClassID = 1, ...
    Position = [44.31 26.45 0.01], ...
    Mesh = driving.scenario.carMesh, ...
    Name = 'Car');
waypoints = [44.31 26.45 0.01;
    38.06 27.66 0.01;
    29.2 28.42 0.01;
    21.1 28 0;
    13.4 26.2 0;
    4.3 20.9 0;
    -1.7 14.3 0;
    -4.8 6.3 0;
    -3.9 -2.6 0;
    -0.43 -7.66 0.01;
    4.38 -11.95 0.01;
    10 -16.2 0;
    16.32 -18.4 0.01;
    24.09 -20.26 0.01;
    33.54 -20.03 0.01;
    40.88 -19.16 0.01;
    47.6 -18.22 0.01];
speed = [50;50;50;50;50;50;50;50;50;50;50;50;50;50;50;50;50];
smoothTrajectory(egoVehicle, waypoints, speed);

% Display the scenario
% plot(scnro,Waypoints = "on");
% while advance(scnro)
%    pause(scnro.SampleTime);
% end

function output = getDetectorOutput(sensor)

if isa(sensor, 'visionDetectionGenerator')
    output = sensor.DetectorOutput;
elseif isa(sensor, 'lidarPointCloudGenerator')
    output = 'PointCloud';
elseif isa(sensor, 'insSensor')
    output = 'INSMeasurement';
else
    output = 'Objects only';
end

